  "tick.read.9": "Infusion d'une tasse fraîche de Liber-Thé…",
  "tick.read.10": "Consultation de l'officier de la Démocratie pour un second avis…",
  "tick.review.1": "Débriefing avec le ministère de la Défense…",
  "tick.review.2": "Vérification de votre serment auprès des archives officielles…",
  "tick.review.3": "On astique une médaille… ou on aiguise une insulte…",
  "tick.review.4": "Décompte des insectes, robots et calmars que vous avez libérés…",
  "tick.review.5": "Visionnage des images de la caméra de casque. Certaines deux fois.",
  "role.HARDPOINT.blurb": "Tient le terrain. Prépare la zone de mort avant le contact pour libérer les emplacements de l'escouade.",
  "role.HAMMER.blurb": "La profondeur antiblindage de l'escouade. Arme les objectifs, tue ce que la zone de mort laisse passer.",
  "role.FORWARD_EYE.blurb": "Opère un temps d'avance. Compense le manque de renseignements ; ne mène jamais la bataille de l'escouade.",
  "role.FIRES.blurb": "Un barrage lourd sur la zone de largage marquée dès que le premier vaisseau de transport s'engage.",
  "role.LONG_ARM.blurb": "Feu soutenu contre le menu fretin et les menaces aériennes. Assure le volume pour que les ancres s'occupent du blindage.",
  "rat.read": "La lecture : {driver}.",
  "rat.growth": "{item} est le choix de progrès — hors de la zone habituelle de {style}, placé là où la mission le récompense, pas comme un handicap.",
  "rat.thin": "{axis} est un point faible — {owner} est solide là-dessus et le couvre.",
  "rat.commando": "Opération Commando : pas d'armes fixes — portez votre arme de soutien et gardez une frappe pour chaque fenêtre du Super Destroyer.",
  "ps.siege_anchor.label": "Ancre de siège",
  "ps.siege_anchor.desc": "Tient le terrain et le fortifie — tourelles, emplacements, position préparée.",
  "ps.danger_close.label": "Danger rapproché",
  "ps.danger_close.desc": "L'artillerie d'abord — Eagles et stratagèmes ouvrent chaque engagement.",
  "ps.fire_for_effect.label": "Tir d'efficacité",
  "ps.fire_for_effect.desc": "Spécialiste du bombardement orbital ; attendrit les cibles avant le contact.",
  "ps.forward_eye.label": "Forward Eye",
  "ps.forward_eye.desc": "Éclaireur mobile — tireur d'élite, couvre le terrain et marque les objectifs devant l'escouade.",
  "ps.by_the_book.label": "Dans les règles",
  "ps.by_the_book.desc": "Généraliste équilibré, sans tendance dominante.",
