  "gl.styles": "Spielstile — aus deinen Karriere-Statistiken gelesen",
  "gl.card": "Auf einer Karte",
  "gl.growth": "Wachstum",
  "gl.growth.d": "Eine bewusst unbequeme Wahl außerhalb deiner Komfortzone, die diese Mission belohnt — so fordert dich der Coach, kein Handicap.",
  "gl.thin": "Schwach",
  "gl.thin.d": "Eine Fähigkeit, bei der du in diesem Einsatz dünn aufgestellt bist — immer von einem benannten Kameraden abgedeckt. Wer, steht in der Fähigkeitsmatrix.",
  "gl.reactive": "Übernimmt die reaktiven Strategem-Calls des Squads.",
  "tick.read.1": "Übermittle deine Dienstakte an das Oberkommando der Super-Erde…",
  "tick.read.2": "Gleiche deine Abschüsse mit dem Wahrheitsministerium ab…",
  "tick.read.3": "Zähle deine Unfälle. Großzügig.",
  "tick.read.4": "Lese jede Zahl zweimal — die Freiheit verlangt Genauigkeit…",
  "tick.read.5": "Kalibriere Freiheit-pro-Minute-Kennzahlen…",
  "tick.read.6": "Bestätige, dass du kein Terminide im Trenchcoat bist…",
  "tick.read.7": "Reiche Form 27-B/Liberty in dreifacher Ausfertigung ein…",
  "tick.read.8": "Fordere orbitale Bestätigung deiner K/D an…",
  "tick.read.9": "Brühe eine frische Tasse Freiheits-Tee auf…",
  "tick.read.10": "Hole beim Demokratieoffizier eine zweite Meinung ein…",
  "tick.review.1": "Debriefing mit dem Verteidigungsministerium…",
  "tick.review.2": "Prüfe deinen Schwur gegen die offizielle Akte…",
  "tick.review.3": "Poliere eine Medaille… oder schärfe eine Beleidigung…",
  "tick.review.4": "Zähle die Käfer, Bots und Tintenfische, die du befreit hast…",
  "tick.review.5": "Sichte Helmkamera-Aufnahmen. Manche zweimal.",
  "role.HARDPOINT.blurb": "Hält die Stellung. Baut die Todeszone vor dem Kontakt auf, damit die Slots des Squads frei werden.",
  "role.HAMMER.blurb": "Die Panzerabwehr-Tiefe des Squads. Schärft Ziele, erledigt, was die Todeszone nicht schafft.",
  "role.FORWARD_EYE.blurb": "Operiert einen Takt voraus. Löst schlechte Aufklärung; kämpft nie die Schlacht des Squads.",
  "role.FIRES.blurb": "Ein schweres Sperrfeuer auf die markierte Landezone, sobald sich das erste Landungsschiff festlegt.",
  "role.LONG_ARM.blurb": "Dauerfeuer gegen Kanonenfutter und Luftziele. Trägt das Volumen, damit die Anker sich um die Panzerung kümmern.",
  "rat.read": "Die Analyse: {driver}.",
  "rat.growth": "{item} ist die Wachstumswahl — außerhalb der üblichen Reichweite von {style}, dort platziert, wo die Mission sie belohnt, kein Handicap.",
  "rat.thin": "{axis} ist schwach — {owner} ist dort stark und deckt es ab.",
  "rat.commando": "Commando-Einsatz: keine stationären Waffen — trag deine Unterstützungswaffe, halte einen Schlag für jedes Super-Zerstörer-Fenster bereit.",
  "ps.siege_anchor.label": "Belagerungsanker",
  "ps.siege_anchor.desc": "Hält die Stellung und befestigt sie — Geschütztürme, Stellungen, eine vorbereitete Position.",
  "ps.danger_close.label": "Gefahr nah",
  "ps.danger_close.desc": "Feuerkraft zuerst — Eagles und Strategeme eröffnen jedes Gefecht.",
  "ps.fire_for_effect.label": "Wirkungsfeuer",
  "ps.fire_for_effect.desc": "Spezialist für Orbitalbombardements; macht Ziele vor dem Kontakt weich.",
  "ps.forward_eye.label": "Forward Eye",
  "ps.forward_eye.desc": "Mobiler Späher — Schütze, deckt Gelände ab, markiert Ziele vor dem Squad.",
  "ps.by_the_book.label": "Nach Vorschrift",
  "ps.by_the_book.desc": "Ausgewogener Allrounder ohne dominante Tendenz.",
