  "gl.growth": "Rozwój",
  "gl.growth.d": "Jeden wybór celowo spoza twojej strefy komfortu, który ta misja nagradza — tak trener cię rozwija, to nie kara.",
  "gl.thin": "Słabo",
  "gl.thin.d": "Zdolność, w której jesteś słabszy na tym zrzucie — zawsze pokryta przez wskazanego kompana. Kto — sprawdź w macierzy zdolności.",
  "gl.reactive": "Odpowiada za reaktywne wezwania stratagemów oddziału.",
  "tick.read.1": "Przesyłanie twoich akt do Naczelnego Dowództwa Super Ziemi…",
  "tick.read.2": "Porównywanie liczby zabójstw z Ministerstwem Prawdy…",
  "tick.read.3": "Liczenie twoich wypadków. Wyrozumiale.",
  "tick.read.4": "Czytanie każdej liczby dwa razy — Wolność wymaga precyzji…",
  "tick.read.5": "Kalibrowanie wskaźników wolności na minutę…",
  "tick.read.6": "Sprawdzanie, czy nie jesteś Terminidem w prochowcu…",
  "tick.read.7": "Wypełnianie Form 27-B/Liberty w trzech egzemplarzach…",
  "tick.read.8": "Prośba o orbitalne potwierdzenie twojego K/D…",
  "tick.read.9": "Parzenie świeżej filiżanki herbatki Wolności…",
  "tick.read.10": "Konsultacja z Oficerem Demokracji dla drugiej opinii…",
  "tick.review.1": "Składanie raportu w Ministerstwie Obrony…",
  "tick.review.2": "Sprawdzanie twojej przysięgi z oficjalnym rejestrem…",
  "tick.review.3": "Polerowanie medalu… albo ostrzenie obelgi…",
  "tick.review.4": "Liczenie robali, botów i kałamarnic, które wyzwoliłeś…",
  "tick.review.5": "Przegląd nagrań z kamery na hełmie. Niektórych dwukrotnie.",
  "role.HARDPOINT.blurb": "Trzyma teren. Buduje strefę śmierci przed kontaktem, żeby zwolnić sloty oddziału.",
  "role.HAMMER.blurb": "Przeciwpancerna głębia oddziału. Uzbraja cele, zabija to, czego nie zabije strefa śmierci.",
  "role.FORWARD_EYE.blurb": "Działa krok przed resztą. Rozwiązuje problem słabego wywiadu; nigdy nie toczy bitwy oddziału.",
  "role.FIRES.blurb": "Jedna ciężka zapora ogniowa na oznaczoną strefę zrzutu, gdy pierwszy desantowiec podchodzi do lądowania.",
  "role.LONG_ARM.blurb": "Ciągły ogień w mięso armatnie i cele powietrzne. Daje wolumen, żeby kotwice zajęły się pancerzem.",
