  "role.HARDPOINT.blurb": "Держит позицию. Строит зону поражения до контакта, чтобы освободить слоты отряда.",
  "role.HAMMER.blurb": "Противотанковый резерв отряда. Активирует цели, добивает то, что не добила зона поражения.",
  "role.FORWARD_EYE.blurb": "Действует на шаг впереди. Решает проблему плохой разведки; никогда не ведёт бой отряда.",
  "role.FIRES.blurb": "Один тяжёлый огневой налёт по отмеченной зоне высадки, как только первый десантный корабль заходит на посадку.",
  "role.LONG_ARM.blurb": "Непрерывный огонь по мелочи и воздушным целям. Берёт на себя объём, чтобы якоря занимались бронёй.",
