  "tick.review.5": "Sisakkamerás felvételek átnézése. Némelyiket kétszer.",
  "role.HARDPOINT.blurb": "Tartja a terepet. A kontaktus előtt kiépíti a halálzónát, így felszabadulnak az osztag slotjai.",
  "role.HAMMER.blurb": "Az osztag páncéltörő tartaléka. Élesíti a célokat, leszedi, amit a halálzóna nem.",
  "role.FORWARD_EYE.blurb": "Egy ütemmel előrébb dolgozik. Megoldja a gyenge felderítést; sosem az osztag harcát vívja.",
  "role.FIRES.blurb": "Egyetlen nehéz zárótűz a megjelölt ledobási zónára, amint az első dropship leszállni indul.",
  "role.LONG_ARM.blurb": "Folyamatos tűz az ágyútöltelékre és légvédelem. Ő viszi a tűzmennyiséget, hogy a horgonyok a páncélra figyelhessenek.",
