  "doctrine.commando.title": "Commando-doktrin",
  "doctrine.commando.1": "Två Super Destroyer-fönster, 60 sekunder vardera — planera varje anrop före det första. Fönster ett: utrustningen du bär hela uppdraget. Fönster två: huvudmålet eller extraheringen.",
  "doctrine.commando.2": "Bestående utrustning först (stödvapen, ryggsäckar). En död dykare tappar sin — hämta den; det finns inget nytt anrop förrän nästa fönster.",
  "doctrine.commando.3": "Hotnivån stiger permanent med varje robotlandning. Döda flare-skyttar och anropare först, gå runt patruller och slåss inte för prover.",
  "doctrine.commando.4": "Förstärkning sker från de 4 kapslarna (3 liv var) — 12 för hela truppen. Markera dem vid landning.",
  "d100.1": "D100 stående order: inga påfyllnadsanrop förrän huvudmålet är klart.",
  "d100.2": "D100 stående order: förstärk bara inom extraheringsräckvidd — varje död kostar truppen terräng.",
  "d100.3": "D100 stående order: inga S-tier-kryckor. Utrustningen är off-meta med flit; få den att funka.",
  "note.plotting": "Komplex stratageminmatning: varje anrop är 2–4 s stillastående. Bara den reaktiva dykaren anropar under eld; alla andra planerar inifrån reläet.",
  "note.poor_intel": "Dålig underrättelse: Forward Eye jobbar ett steg före så att målen hittas utan att truppen letar som fyra.",
  "note.city": "Stadskarta: korta siktlinjer och luftburna hot. Värn förlorar skjutvinklar; luftvärn och intrångsverktyg ökar i värde.",
  "note.mandated": "Kartan kräver: {list}.",
  "note.recovery": "Återhämtning: förstärk aldrig in i kontakt; fortsätt från senast avslutade steg; om den bärande tillgången dör stoppas sekvensen tills den är tillbaka.",
