  "tick.read.9": "Nagtitimpla ng bagong tasa ng Liber-Tea…",
  "tick.read.10": "Kinukonsulta ang Democracy Officer para sa second opinion…",
  "tick.review.1": "Nagde-debrief kasama ang Ministry of Defense…",
  "tick.review.2": "Kinukumpara ang panunumpa mo sa official record…",
  "tick.review.3": "Nagpapakintab ng medalya… o naghahasa ng insulto…",
  "tick.review.4": "Binibilang ang mga bug, bot at pusit na na-liberate mo…",
  "tick.review.5": "Nirereview ang helmet-cam footage. Yung iba, dalawang beses.",
  "role.HARDPOINT.blurb": "Hawak ang posisyon. Binubuo ang killzone bago mag-contact para ma-free ang slots ng squad.",
  "role.HAMMER.blurb": "Ang anti-armor depth ng squad. Nag-a-arm ng objectives, pinapatay ang hindi kaya ng killzone.",
  "role.FORWARD_EYE.blurb": "Isang beat na nauuna. Sinosolusyunan ang poor intel; hindi kailanman nakikipaglaban sa laban ng squad.",
  "role.FIRES.blurb": "Isang mabigat na barrage sa minarkahang drop zone pagka-commit ng unang dropship.",
  "role.LONG_ARM.blurb": "Tuloy-tuloy na chaff clear at anti-air. Siya ang bahala sa volume para armor ang tutukan ng anchors.",
  "rat.read": "Ang read ay {driver}.",
