  "rat.commando": "Commando op: walang statics — dalhin ang support weapon mo, magtabi ng isang strike para sa bawat Super Destroyer window.",
  "ps.siege_anchor.label": "Siege Anchor",
  "ps.siege_anchor.desc": "Humahawak at nagpapatibay ng posisyon — turrets, emplacements, nakahandang puwesto.",
  "ps.danger_close.label": "Danger Close",
  "ps.danger_close.desc": "Ordnance muna — Eagles at stratagems ang nangunguna sa bawat engagement.",
